out = ['/* icons.css — آیکون‌های خطی به سبک Lucide (ISC License, lucide.dev) به‌صورت mask؛ رنگ = currentColor. تولیدشده؛ دستی ویرایش نشود.',
       ' * استفاده: <i class="ico ico-check"></i> — اندازه = 1em (با font-size والد). */',
       '.ico { display: inline-block; width: 1.05em; height: 1.05em; flex: none; vertical-align: -0.17em; background-color: currentColor;',
       '  -webkit-mask: var(--ico) center / contain no-repeat; mask: var(--ico) center / contain no-repeat; }',
       '[dir="rtl"] .ico-send, [dir="rtl"] .ico-arrow-left { transform: scaleX(-1); }']
for name, v in I.items():
    body, fill = (v if isinstance(v, tuple) else (v, False))
    attrs = 'fill="black" stroke="black" stroke-width="1.5"' if fill else 'fill="none" stroke="black" stroke-width="2"'
    svg = f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" {attrs} stroke-linecap="round" stroke-linejoin="round">{body}</svg>'
    out.append(f'.ico-{name} {{ --ico: url("data:image/svg+xml,{urllib.parse.quote(svg, safe=" =:/,.-")}"); }}')
open(sys.argv[1], 'w', encoding='utf-8', newline='\n').write('\n'.join(out) + '\n')
print(len(I), 'icons')
